Mesh<Point, double> result;

// Iterate over all edges in the regular triangulation
for (auto eit = rt.edges_begin(); eit != rt.edges_end(); ++eit) {
    // Check if this edge is above the threshold (not small)
    if (!is_small_edge(rt, *eit, threshold)) {
        // Get the edge vertices
        RT::Cell_handle c = eit->first;
        int i = eit->second;
        int j = eit->third;

        // Get the segment for this edge to calculate its length
        Segment seg = rt.segment(*eit);
        double length = std::sqrt(seg.squared_length());

        // Collect the incident cells as polygons
        std::vector<unsigned> vertices;

        // For a power diagram face, we need to collect the vertices that define the face
        // In a 3D regular triangulation, an edge is shared by multiple cells
        // The vertices of the power diagram face are the dual vertices of the cells incident to this edge

        // Get the two vertices of the edge
        Point p1 = c->vertex(i)->point().point();
        Point p2 = c->vertex(j)->point().point();

        // Add the vertices to our mesh (indices or actual points)
